-- Quinn Quigley (profileID=17) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Quinn Quigley phrasings

SELECT p.argumentID, p.phrasingID, 17, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 17
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 17 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=17 AND targArgID IN (80,89,90,104,105,107,110,136,142,143,144,151,217,218,219,278,288,293,294,295,296,297,315,316,367,368,369,374,422,481,482,483,494,495,496,500,501,502,539,543,544,546,547,556,557,558,560,561,574,575,576,588,597,682,683,684,685,692,693,696,719,721,722,763,766,767,768,785,790,791,792,793,795,797,800,801,836,1143,1200,1201,1312,1425,1429);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 17
SET pe.active = o.acceptance
WHERE pe.profileID = 17;

SELECT 'Done: endorsements for profileID=17' AS status;